@startuml

class Doctor {
  + practitionerNumber : string
  + fullName : string
  + address : string
  + phoneNumber : string
  + signature : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
  + repetitionCount : int
  + repetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

class Test {
  + duration : int
}

class TestGroup {
  + name : string
}

class Lab {
  + address : string
  + registrationNumber : string
  + businessHoursStart : time
  + businessHoursEnd : time
  + cancellationFee : float
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class TestResult {
  + resultValue : string
  + report : string
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" -- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Test "1" -- "0..*" TestResult : produces
Patient "1" -- "*" TestResult : views
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" Appointment : books
Appointment "1" -- "1" Lab : at
Appointment "1" -- "1" Test : for
Appointment "*" -- "1" Requisition : for

@enduml

